<?php
declare(strict_types=1);
require_once __DIR__.'/api/lib/christmas-advent-2026-claim.php';
function t(bool $v,string $s):void{if(!$v)throw new RuntimeException($s);echo "PASS: $s\n";}
function db():SQLite3{$d=new SQLite3(':memory:');$d->enableExceptions(true);$d->exec('PRAGMA foreign_keys=ON');$d->exec('CREATE TABLE tbl_users(discord_id TEXT PRIMARY KEY,username TEXT NOT NULL)');$d->exec('CREATE TABLE tbl_user_scores(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,game TEXT,score INTEGER,timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,source TEXT)');$d->exec("CREATE TABLE tbl_score_adjustments(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,admin_id TEXT NOT NULL,amount INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN ('add','remove','set')),reason TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES tbl_users(discord_id),FOREIGN KEY(admin_id) REFERENCES tbl_users(discord_id))");$d->exec((string)file_get_contents(__DIR__.'/db/migrations/create_christmas_advent_2026_claims_v1.sql'));return$d;}
function policy():array{$r=[];$c=[];for($i=1;$i<=24;$i++){$r[$i]=$i===24?25000:5000;$c[$i]=$i===24?25000000:5000000;}$p=['version'=>CHRISTMAS26_POLICY_VERSION,'rewards'=>$r,'daily_caps'=>$c,'per_user_cap'=>140000,'event_cap'=>140000000];$p['fingerprint']=christmas26_claim_policy_fingerprint($p);return$p;}
t(!christmas26_claim_payout_is_enabled(null,null),'payout gate defaults off');t(christmas26_claim_payout_is_enabled('1',CHRISTMAS26_POLICY_VERSION),'exact policy gate required');t(christmas26_claim_origin_is_allowed(['HTTP_ORIGIN'=>'https://narrrfs.world'])&&!christmas26_claim_origin_is_allowed(['HTTP_ORIGIN'=>'https://evil.test']),'strict origin validation');
$s=[];$token=christmas26_claim_issue_csrf($s);t(christmas26_claim_csrf_is_valid($s,$token)&&!christmas26_claim_csrf_is_valid($s,$token),'one-time csrf validation');
$d=db();$u='111111111111111111';$d->exec("INSERT INTO tbl_users VALUES('$u','test')");$now=new DateTimeImmutable('2026-12-01 12:00:00',new DateTimeZone('Europe/Vienna'));$r=christmas26_claim_execute($d,$u,$now,policy());t(!$r['replayed']&&(int)$d->querySingle('SELECT COUNT(*) FROM tbl_christmas_advent_2026_claims')===1,'atomic initial claim');$again=christmas26_claim_execute($d,$u,$now,policy());t($again['replayed']&&$again['claim_id']===$r['claim_id']&&(int)$d->querySingle('SELECT COUNT(*) FROM tbl_user_scores')===1,'lost-response replay does not pay twice');
$d2=db();$d2->exec("INSERT INTO tbl_users VALUES('$u','test')");try{christmas26_claim_execute($d2,$u,$now,policy(),static function(string $p):void{if($p==='after_score')throw new RuntimeException('forced');});}catch(Throwable){}t((int)$d2->querySingle('SELECT COUNT(*) FROM tbl_user_scores')===0&&(int)$d2->querySingle('SELECT COUNT(*) FROM tbl_christmas_advent_2026_claims')===0,'forced failure fully rolls back');
$bad=policy();$bad['daily_caps'][1]=4999;$bad['fingerprint']=christmas26_claim_policy_fingerprint($bad);try{christmas26_claim_execute($d2,$u,$now,$bad);$ok=false;}catch(Throwable $e){$ok=$e->getMessage()==='budget_exhausted';}t($ok,'budget exhaustion fails before writes');t((int)$d2->querySingle('PRAGMA foreign_keys')===1,'foreign keys remain enabled');echo "PASS: disposable V4 claim suite complete\n";